return {
    ts: ctx.latestTs,
    values: {
        fuelRate: getRate()
    }
};


function getRate() {
    if (fuelLevel.count() < 2) {
        return 0;
    }
    var first = fuelLevel.first();
    var last = fuelLevel.last();


    if (isNaN(first) || isNaN(last)) {
        return 0;
    }

    var deltaLevel = first - last;
    if (deltaLevel <= 0) {
        return 0;
    }
    return toFixed(deltaLevel, 2);
}
